import {round} from './geometry.js?v=9-office-chair';
import {wallFrame,wallNames,furnitureNames} from './room.js?v=9-office-chair';
export const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function roomItem(s,target){return target.startsWith('feature:')?s.roomFeatures.find(v=>v.id===target.slice(8)):target.startsWith('furniture:')?s.roomFurniture.find(v=>v.id===target.slice(10)):null;}
export function roomValue(s,target,key){const item=roomItem(s,target);if(!item)return key==='x'?round(s[target+'X']-s.roomX):key==='z'?round(s[target+'Z']-s.roomZ):s[target+'Angle'];return key==='x'?round(item.x-s.roomX):key==='z'?round(item.z-s.roomZ):item[key];}
export function roomControls(s,e,target,range,toggle){
 const item=roomItem(s,target),active=item||['desk','cockpit'].includes(target)?target:'desk',a=escapeHTML;
 const num=(key,label,min,max,step=1,unit='cm')=>{const value=roomValue(s,active,key);return `<div class="control room-object-control"><div class="control-top"><label for="room-${key}-range">${label}</label><div class="number-wrap"><input id="room-${key}-number" type="number" data-room-key="${key}" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}"><span>${unit}</span></div></div><input id="room-${key}-range" type="range" data-room-key="${key}" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}" style="--pct:${(value-min)/(max-min)*100}%"></div>`;};
 const sel=(key,label,options)=>`<div class="select-control"><label for="room-${key}">${label}</label><select id="room-${key}" data-room-key="${key}">${options.map(([v,n])=>`<option value="${v}" ${item?.[key]===v?'selected':''}>${a(n)}</option>`).join('')}</select></div>`;
 const group=(title,body)=>`<div class="control-group"><h3 class="group-title">${title}</h3>${body}</div>`;
 let html=group('Medidas interiores',toggle('roomEnabled','Mostrar habitación y comprobar obstáculos')+range('roomW','Ancho de pared AB')+range('roomD','Fondo de pared BC')+range('roomH','Altura de techo')+toggle('roomFullWalls','Mostrar paredes completas en 3D')+`<details class="room-reference"><summary>Referencia y espacio de paso</summary>${range('roomX','Origen X de la habitación')+range('roomZ','Origen Z de la habitación')+range('aisle','Reserva lateral deseada')}<p class="layout-hint">Cambiar el origen mueve las paredes. Mesa, cockpit y muebles conservan su posición.</p></details><div class="room-actions"><button id="roomFrame">Ver habitación en planta</button><button id="roomCenter">Centrar mesa y cockpit</button></div>`);
 html+=group('Puertas, ventanas y muebles',`<div class="room-add-grid"><button data-add-room="door">＋ Puerta</button><button data-add-room="window">＋ Ventana</button><button data-add-room="chair">＋ Silla de PC</button><button data-add-room="shelf">＋ Estantería</button><button data-add-room="wardrobe">＋ Armario / otro</button></div>${!s.roomFeatures.length&&!s.roomFurniture.length?'<p class="room-empty">Añade los huecos y muebles de tu habitación. Tus medidas anteriores se conservan.</p>':''}<div class="select-control target-picker"><label for="roomTarget">Elemento seleccionado</label><select id="roomTarget"><optgroup label="Tu setup"><option value="desk" '+(active==='desk'?'selected':'')+'>Escritorio completo</option><option value="cockpit" '+(active==='cockpit'?'selected':'')+'>Cockpit</option></optgroup>${s.roomFeatures.length?'<optgroup label="En las paredes">'+s.roomFeatures.map(v=>`<option value="feature:${v.id}" ${active==='feature:'+v.id?'selected':''}>${a(v.name)}</option>`).join('')+'</optgroup>':''}${s.roomFurniture.length?'<optgroup label="Muebles">'+s.roomFurniture.map(v=>`<option value="furniture:${v.id}" ${active==='furniture:'+v.id?'selected':''}>${a(v.name)}</option>`).join('')+'</optgroup>':''}</select></div>`);
 let editor='';
 if(item)editor+=`<div class="room-name"><label for="roomName">Nombre</label><input id="roomName" data-room-key="name" value="${a(item.name)}" maxlength="45"></div>`;
 if(item?.wall){
  const frame=wallFrame(s,item.wall);
  editor+=sel('wall','Pared',Object.entries(wallNames))+num('offset',`Inicio del hueco desde ${frame.corner}`,0,frame.length-item.width,.5)+num('width','Ancho del hueco',30,Math.min(300,frame.length))+num('height','Altura del hueco',30,s.roomH);
  if(item.type==='door')editor+=sel('hinge','Bisagras',[['start',`Inicio del hueco · cerca de ${frame.corner}`],['end','Final del hueco']])+sel('swing','Sentido de apertura',[['in','Hacia dentro'],['out','Hacia fuera']])+num('openAngle','Ángulo que debe poder abrir',0,180,1,'°')+'<p class="layout-hint">El área naranja comprueba todo el barrido desde cerrada hasta este ángulo. Arrastra el hueco a lo largo de su pared; cambia de pared con el selector.</p>';
  else editor+=num('sill','Antepecho desde el suelo',0,s.roomH-item.height)+num('clearance','Reserva libre delante',0,150)+'<p class="layout-hint">La franja azul reserva acceso. El antepecho sitúa la ventana en altura; no se simula el giro de sus hojas.</p>';
 }else{
  if(item){const chair=item.type==='chair';editor+=sel('type','Tipo de mueble',Object.entries(furnitureNames))+num('width',chair?'Ancho total de la silla':'Ancho del mueble',chair?40:10,chair?100:350)+num('depth',chair?'Fondo total de la silla':'Fondo del mueble',chair?40:10,chair?100:250)+num('height',chair?'Altura total de la silla':'Altura del mueble',chair?70:10,chair?180:350);if(chair)editor+=num('seatHeight','Altura del asiento',30,Math.min(65,item.height-20))+num('pullback','Espacio para retirar la silla',0,150)+'<button class="arm-edit-action" id="chairAtDesk">Colocar frente al escritorio ↗</button><p class="layout-hint">La huella incluye ruedas y reposabrazos. La franja trasera reserva espacio para apartar la silla; ponla a 0 para ocultarla. La silla se mueve independientemente de la mesa.</p>';}
  editor+=num('x','Posición X desde pared DA',-200,s.roomW+200,.5)+num('z','Posición Z desde pared AB',-200,s.roomD+200,.5)+num('angle','Giro en planta',0,359,1,'°')+`<div class="rotate-actions"><button data-room-rotate="-90">↶ −90°</button><button data-room-rotate="90">+90° ↷</button></div><p class="layout-hint">${active==='cockpit'?'Referencia: centro del extremo trasero del chasis.':'Referencia: centro del elemento.'} Arrastra en planta o escribe las distancias a las paredes.</p>`;
 }
 if(item)editor+='<button class="room-delete" id="roomDelete">Eliminar este elemento</button>';
 html+=group(item?escapeHTML(item.name):active==='cockpit'?'Colocar cockpit':'Colocar escritorio',editor);
 html+='<p class="control-hint">Paredes A–B–C–D en sentido horario desde la esquina superior izquierda. Se comprueban límites, muebles y barrido de puerta con envolventes aproximadas. La reserva lateral no garantiza una ruta continua de entrada.</p>';
 return html;
}
